#!/usr/bin/env bash
# Build and run the Pretzuri feed worker on the NAS (run from the workstation, Git Bash).
#   infra/nas/deploy-worker.sh dev
#   infra/nas/deploy-worker.sh prod --yes
# Only touches <env folder>/worker and the worker compose project (see lib/project.sh).
# The DB password (FEED_WORKER_DB_PASSWORD, generated by remote-apply.sh in supabase/.env) never leaves the NAS:
# the role gets a SCRAM verifier (computed in the worker image, so the plaintext is not in the DB log) and the
# connection string goes to worker.secret.env (mode 600), together with the Storage service_role key
# (STORAGE_SERVICE_KEY, same handling: read on the NAS, never printed).
set -euo pipefail

ENV="${1:?usage: deploy-worker.sh <dev|prod> [--yes]}"
case "$ENV" in dev|prod) ;; *) echo "env must be dev or prod" >&2; exit 1 ;; esac
if [ "$ENV" = "prod" ] && [ "${2:-}" != "--yes" ]; then
  echo "refusing to deploy PROD without --yes" >&2; exit 1
fi

HERE="$(cd "$(dirname "$0")" && pwd)"
. "$HERE/lib/project.sh"; nas_resolve "$ENV"
PROJECT="$NAS_WORKER_PROJECT"
BASE="$NAS_BASE"
REMOTE="$BASE/worker"
ROOT="$HERE/../.."

echo "==> syncing worker source to $NAS_HOST:$REMOTE/src"
nas_ssh "mkdir -p '$REMOTE/src' && rm -rf '$REMOTE/src/'* '$REMOTE/src/.'[!.]* 2>/dev/null; true"
tar -C "$ROOT/worker" -czf - --exclude='./node_modules' --exclude='./dist' --exclude='.env*' . \
  | nas_ssh "tar -C '$REMOTE/src' -xzf -"
nas_ssh "cat > '$REMOTE/worker.env'" < "$HERE/env/worker-$ENV.env"
nas_ssh "cat > '$REMOTE/docker-compose.yml'" < "$ROOT/infra/worker/docker-compose.yml"

echo "==> building pretzuri-worker:$ENV, setting the feed_worker login, starting $PROJECT"
nas_ssh "sh -s" <<REMOTE_SCRIPT
set -eu
export PATH=\$PATH:/usr/local/bin
cd '$REMOTE'
umask 077
SENV='$BASE/supabase/.env'
PW=\$(grep '^FEED_WORKER_DB_PASSWORD=' "\$SENV" | cut -d= -f2-)
[ -n "\$PW" ] || { echo "FEED_WORKER_DB_PASSWORD not found (run deploy-supabase.sh first)" >&2; exit 1; }
DBNAME=\$(grep '^POSTGRES_DB=' "\$SENV" | cut -d= -f2- || true); DBNAME=\${DBNAME:-postgres}
DBPORT=\$(grep '^POSTGRES_PORT=' "\$SENV" | cut -d= -f2- || true); DBPORT=\${DBPORT:-5432}
# Storage uploads (image cache): service_role key, read here on the NAS, written only to worker.secret.env (600).
SRK=\$(grep '^SERVICE_ROLE_KEY=' "\$SENV" | cut -d= -f2- || true)

nice -n 10 docker build -q -t "pretzuri-worker:$ENV" src

VERIFIER=\$(printf '%s' "\$PW" | docker run --rm -i --network none "pretzuri-worker:$ENV" node dist/tools/scram-verifier.js)
case "\$VERIFIER" in SCRAM-SHA-256*) ;; *) echo "could not compute the password verifier" >&2; exit 1 ;; esac
printf "alter role feed_worker login password '%s';\n" "\$VERIFIER" \
  | (cd '$BASE/supabase' && docker compose -p '$NAS_PROJECT' exec -T db psql -U postgres -X -q -v ON_ERROR_STOP=1 >/dev/null)
unset VERIFIER

printf 'DATABASE_URL=postgres://feed_worker:%s@db:%s/%s\n' "\$PW" "\$DBPORT" "\$DBNAME" > worker.secret.env
if [ -n "\$SRK" ]; then printf 'STORAGE_SERVICE_KEY=%s\n' "\$SRK" >> worker.secret.env; else echo "warning: SERVICE_ROLE_KEY not found, the image cache stays off" >&2; fi
chmod 600 worker.secret.env
unset PW SRK

docker compose -p '$PROJECT' --env-file worker.env up -d --force-recreate
sleep 5
docker compose -p '$PROJECT' --env-file worker.env ps
docker compose -p '$PROJECT' --env-file worker.env logs --tail 20 worker
REMOTE_SCRIPT
